"""Regenerates src/fir.rs (48-tap Kaiser low-pass, fc 7.2 kHz at 48 kHz, Q15)."""
import numpy as np
N, fs, fc = 48, 48000, 7200
n = np.arange(N) - (N - 1) / 2
h = 2 * fc / fs * np.sinc(2 * fc / fs * n) * np.kaiser(N, 7.0)
h /= h.sum()
q = np.round(h * 32768).astype(int)
q[N // 2] += 32768 - q.sum()
open('src/fir.rs', 'w').write(
    '//! 48-tap Kaiser-windowed low-pass FIR (fc 7.2 kHz @ 48 kHz), Q15, unity DC gain.\n'
    '//! Used for 48k->16k decimation and 16k->48k interpolation. Generated by tools/gen_fir.py\n'
    f'pub const TAPS: usize = {N};\npub const FIR_Q15: [i32; TAPS] = [{", ".join(map(str, q))}];\n')
